export const envelope = [38, 18, 56];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 4;

  // Theme-aware ground and masonry with safe defaults
  const groundPavement = api.theme?.ground?.pavement || "minecraft:sandstone";
  const stonePrimary = api.theme?.stone?.primary || "minecraft:smooth_sandstone";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:smooth_sandstone_slab[type=bottom]";

  // Fossil & Mineral materials
  const BONE_Y = "minecraft:bone_block[axis=y]";
  const BONE_X = "minecraft:bone_block[axis=x]";
  const BONE_Z = "minecraft:bone_block[axis=z]";
  const CALCITE = "minecraft:calcite";
  const DEAD_BRAIN = "minecraft:dead_brain_coral_block";
  const DEAD_TUBE = "minecraft:dead_tube_coral_block";
  const DEAD_HORN = "minecraft:dead_horn_coral_block";
  const DRIPSTONE = "minecraft:dripstone_block";
  const FANG_DOWN = "minecraft:pointed_dripstone[thickness=base,vertical_direction=down]";
  const FANG_UP = "minecraft:pointed_dripstone[thickness=base,vertical_direction=up]";

  // 3D voxel grid buffer
  const grid = new Array(W * H * D).fill(null);

  function getIdx(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return -1;
    return (y * D + z) * W + x;
  }

  function getBlock(x, y, z) {
    const idx = getIdx(x, y, z);
    return idx === -1 ? null : grid[idx];
  }

  function setBlock(x, y, z, block) {
    const idx = getIdx(x, y, z);
    if (idx !== -1) grid[idx] = block;
  }

  // Deterministic noise for weathering & texture variation
  const seed = api.random() * 1000;
  function noise(x, y, z) {
    const n = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719 + seed) * 43758.5453;
    return n - Math.floor(n);
  }

  // Leviathan spine curves
  function spineX(z) {
    return 19 + Math.sin((z - 8) * 0.13) * 4.2 + Math.cos((z - 20) * 0.08) * 1.5;
  }

  function spineY(z) {
    if (z < 12) return 7.5 + (12 - z) * 0.2;
    if (z < 28) return 10.5 + Math.sin(((z - 12) / 16) * Math.PI) * 3.8;
    if (z < 40) return 8.0 + Math.sin(((z - 28) / 12) * Math.PI) * 2.2;
    return 7.0 - (z - 40) * 0.25;
  }

  // 3D Bone capsule generator
  function drawBoneSegment(x1, y1, z1, x2, y2, z2, radius, defaultAxis = "y") {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const dz = z2 - z1;
    const len = Math.hypot(dx, dy, dz);
    if (len === 0) return;

    let axis = defaultAxis;
    const adx = Math.abs(dx), ady = Math.abs(dy), adz = Math.abs(dz);
    if (adx >= ady && adx >= adz) axis = "x";
    else if (ady >= adx && ady >= adz) axis = "y";
    else axis = "z";

    const r2 = radius * radius;
    const minX = Math.max(0, Math.floor(Math.min(x1, x2) - radius - 1));
    const maxX = Math.min(W - 1, Math.ceil(Math.max(x1, x2) + radius + 1));
    const minY = Math.max(0, Math.floor(Math.min(y1, y2) - radius - 1));
    const maxY = Math.min(H - 1, Math.ceil(Math.max(y1, y2) + radius + 1));
    const minZ = Math.max(0, Math.floor(Math.min(z1, z2) - radius - 1));
    const maxZ = Math.min(D - 1, Math.ceil(Math.max(z1, z2) + radius + 1));

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const px = x - x1, py = y - y1, pz = z - z1;
          const t = Math.max(0, Math.min(1, (px * dx + py * dy + pz * dz) / (len * len)));
          const cx = x1 + t * dx, cy = y1 + t * dy, cz = z1 + t * dz;
          const distSq = (x - cx) * (x - cx) + (y - cy) * (y - cy) + (z - cz) * (z - cz);

          if (distSq <= r2) {
            const nVal = noise(x, y, z);
            let blk;
            if (nVal < 0.12) blk = DEAD_BRAIN;
            else if (nVal < 0.22) blk = DEAD_TUBE;
            else if (nVal < 0.42) blk = CALCITE;
            else blk = `minecraft:bone_block[axis=${axis}]`;
            setBlock(x, y, z, blk);
          }
        }
      }
    }
  }

  // 1. SALT CRUST & SEDIMENTARY DUNES
  // Mounds formed where the ancient carcass trapped windblown salt & sand
  for (let x = 2; x <= 35; x++) {
    for (let z = 2; z <= 53; z++) {
      const sx = spineX(z);
      const distFromSpine = Math.abs(x - sx);

      let duneH = 0;
      // Skull mound
      const dSkull = Math.hypot(x - spineX(8), z - 8);
      if (dSkull < 8.5) duneH = Math.max(duneH, 5.2 - dSkull * 0.35);

      // Mid-body dune (partially engulfing low spine)
      const dMid = Math.hypot(x - spineX(32), z - 32);
      if (dMid < 9.0) duneH = Math.max(duneH, 6.4 - dMid * 0.38);

      // Caudal dune at the tail
      const dTail = Math.hypot(x - spineX(50), z - 50);
      if (dTail < 7.5) duneH = Math.max(duneH, 5.2 - dTail * 0.35);

      // Rib baseline connection bed
      if (distFromSpine < 14 && z >= 14 && z <= 44) {
        duneH = Math.max(duneH, 4.0);
      }

      const topY = Math.floor(duneH);
      if (topY >= SEAT_Y) {
        for (let y = SEAT_Y; y <= topY; y++) {
          const nVal = noise(x, y, z);
          let blk;
          if (y === topY) {
            blk = nVal < 0.65 ? CALCITE : stonePrimary;
          } else if (y === topY - 1) {
            blk = nVal < 0.5 ? CALCITE : groundPavement;
          } else {
            blk = groundPavement;
          }
          setBlock(x, y, z, blk);
        }
      }
    }
  }

  // 2. VERTEBRAL COLUMN & NEURAL PROCESSES
  // Continuous spinal core
  for (let z = 12; z <= 52; z++) {
    const x1 = spineX(z);
    const y1 = spineY(z);
    const x2 = spineX(z + 1);
    const y2 = spineY(z + 1);
    const rad = 1.6 - (z - 12) * 0.015;
    drawBoneSegment(x1, y1, z, x2, y2, z + 1, rad, "z");
  }

  // Distinct Vertebrae with Neural Spines & Transverse Wings
  const vertZ = [12, 15, 18, 21, 24, 27, 30, 33, 36, 39, 42, 45, 48, 51];
  for (let i = 0; i < vertZ.length; i++) {
    const vz = vertZ[i];
    const vx = spineX(vz);
    const vy = spineY(vz);
    const rad = 1.8 - (vz - 12) * 0.018;

    // Centrum bulb
    drawBoneSegment(vx, vy, vz - 0.6, vx, vy, vz + 0.6, rad + 0.3, "z");

    // Neural Spine (tall dorsal crest)
    const spineHeight = 3.8 * Math.sin(((vz - 10) / 42) * Math.PI) + 0.8;
    drawBoneSegment(vx, vy + rad, vz, vx, vy + rad + spineHeight, vz, 0.9, "y");

    // Transverse processes (lateral wing struts)
    const wingSpan = 3.6 - (vz - 12) * 0.045;
    drawBoneSegment(vx - wingSpan, vy, vz, vx + wingSpan, vy, vz, 0.8, "x");
  }

  // 3. MASSIVE RIBCAGE (10 Pairs)
  const ribZ = [15, 18, 21, 24, 27, 30, 33, 36, 39, 42];
  const ribRadiiX = [9.0, 11.5, 13.0, 12.5, 11.0, 9.5, 8.0, 6.8, 5.5, 4.5];
  const ribRadiiY = [3.0, 3.8, 4.2, 4.0, 3.5, 3.0, 2.5, 2.2, 1.8, 1.5];

  for (let k = 0; k < ribZ.length; k++) {
    const rz = ribZ[k];
    const rx = spineX(rz);
    const ry = spineY(rz);
    const spanX = ribRadiiX[k];
    const spanY = ribRadiiY[k];

    for (const side of [-1, 1]) {
      // Intentional weathering & fractures on select ribs
      let maxSteps = 18;
      if (k === 2 && side === 1) maxSteps = 11; // Shattered right rib 3
      if (k === 4 && side === -1) maxSteps = 13; // Broken left rib 5
      if (k === 7 && side === 1) maxSteps = 9;  // Snapped right rib 8

      let prevPx = rx;
      let prevPy = ry;
      let prevPz = rz;

      for (let s = 1; s <= maxSteps; s++) {
        const theta = (s / 18) * Math.PI;
        const curPx = rx + side * (spanX * Math.pow(Math.sin(theta), 0.85));
        const curPy = ry + spanY * Math.sin(theta) - (1 - Math.cos(theta)) * ((ry - 3.8) / 2.0);
        const curPz = rz + side * Math.sin(theta) * 1.2 + (1 - Math.cos(theta)) * 0.5;
        const ribThickness = 1.3 - 0.3 * (s / 18);

        drawBoneSegment(prevPx, prevPy, prevPz, curPx, curPy, curPz, ribThickness);

        prevPx = curPx;
        prevPy = curPy;
        prevPz = curPz;
      }

      // If fractured, add a jagged bone splinter
      if (maxSteps < 18) {
        const nVal = noise(prevPx, prevPy, prevPz);
        const splinterBlock = nVal < 0.5 ? CALCITE : DEAD_TUBE;
        setBlock(Math.round(prevPx), Math.round(prevPy), Math.round(prevPz), splinterBlock);
      }
    }
  }

  // 4. PECTORAL & PELVIC VESTIGIAL FIN RAYS
  // Pectoral Paddles (Z = 16..20)
  for (const side of [-1, 1]) {
    const sx = spineX(18);
    // Ray 1
    drawBoneSegment(sx + side * 5, SEAT_Y, 16, sx + side * 11, SEAT_Y, 14, 0.9, "x");
    // Ray 2
    drawBoneSegment(sx + side * 5, SEAT_Y, 18, sx + side * 13, SEAT_Y, 18, 1.0, "x");
    // Ray 3
    drawBoneSegment(sx + side * 5, SEAT_Y, 20, sx + side * 10, SEAT_Y, 22, 0.8, "x");
  }

  // Pelvic Paddles (Z = 41..44)
  for (const side of [-1, 1]) {
    const sx = spineX(42);
    drawBoneSegment(sx + side * 3, SEAT_Y, 41, sx + side * 8, SEAT_Y, 43, 0.7, "x");
    drawBoneSegment(sx + side * 3, SEAT_Y, 43, sx + side * 7, SEAT_Y, 46, 0.7, "x");
  }

  // 5. ANCIENT LEVIATHAN SKULL (Z = 3 to 13)
  // Facing North (-Z direction)
  const skullBaseZ = 13;
  const snoutTipZ = 3;

  for (let z = snoutTipZ; z <= skullBaseZ; z++) {
    const sx = spineX(z);
    const progress = (z - snoutTipZ) / (skullBaseZ - snoutTipZ); // 0 (snout) to 1 (cranium)
    const jawWidth = 1.6 + progress * 3.6;
    const topY = 7.5 + Math.sin(progress * Math.PI) * 4.2;
    const botY = 5.2 + progress * 0.8;

    // Upper Cranium & Rostrum
    for (let x = Math.floor(sx - jawWidth); x <= Math.ceil(sx + jawWidth); x++) {
      for (let y = Math.floor(botY); y <= Math.ceil(topY); y++) {
        const dx = (x - sx) / jawWidth;
        const dy = (y - (botY + topY) / 2) / ((topY - botY) / 2 || 1);
        const distSq = dx * dx + dy * dy;

        if (distSq <= 1.05) {
          // Eye sockets (orbits) at Z = 9..11
          const isOrbit = z >= 9 && z <= 11 && Math.abs(dx) > 0.65 && y >= 7 && y <= 9;
          // Nasal cavity / blowhole at Z = 6..7 on top
          const isBlowhole = z >= 6 && z <= 7 && Math.abs(x - sx) <= 0.8 && y >= topY - 1;

          if (!isOrbit && !isBlowhole) {
            const nVal = noise(x, y, z);
            let blk;
            if (nVal < 0.15) blk = DEAD_BRAIN;
            else if (nVal < 0.35) blk = CALCITE;
            else blk = BONE_Y;
            setBlock(x, y, z, blk);
          }
        }
      }
    }

    // Sagittal dorsal crest on skull top
    if (z >= 8 && z <= 13) {
      setBlock(Math.round(sx), Math.ceil(topY) + 1, z, BONE_Y);
      if (z >= 10 && z <= 12) {
        setBlock(Math.round(sx), Math.ceil(topY) + 2, z, CALCITE);
      }
    }
  }

  // Mandible (Lower Jaw) - sweeping forward and slightly open
  for (let z = snoutTipZ; z <= skullBaseZ; z++) {
    const sx = spineX(z);
    const progress = (z - snoutTipZ) / (skullBaseZ - snoutTipZ);
    const mandWidth = 1.2 + progress * 3.8;
    const mandY = 4.0 + Math.pow(progress, 1.8) * 2.2;

    for (const side of [-1, 1]) {
      const mx = sx + side * mandWidth;
      drawBoneSegment(mx, mandY, z, mx, mandY, z + 1, 1.0, "z");
    }

    // Chin connection at the front tip
    if (z === snoutTipZ) {
      drawBoneSegment(sx - mandWidth, mandY, z, sx + mandWidth, mandY, z, 1.1, "x");
    }
  }

  // Fangs & Pointed Teeth along upper & lower jaws
  for (let z = 4; z <= 10; z += 2) {
    const sx = spineX(z);
    const progress = (z - snoutTipZ) / (skullBaseZ - snoutTipZ);
    const jawW = 1.4 + progress * 3.5;
    for (const side of [-1, 1]) {
      const tx = Math.round(sx + side * jawW);
      // Upper fangs pointing down
      const upperY = Math.floor(5.5 + progress * 0.8);
      if (getBlock(tx, upperY, z) && !getBlock(tx, upperY - 1, z)) {
        setBlock(tx, upperY - 1, z, FANG_DOWN);
      }
      // Lower fangs pointing up
      const mandY = Math.round(4.0 + Math.pow(progress, 1.8) * 2.2);
      if (getBlock(tx, mandY, z) && !getBlock(tx, mandY + 1, z)) {
        setBlock(tx, mandY + 1, z, FANG_UP);
      }
    }
  }

  // Clear hollow Cranial Vault / Interior Room
  const vaultCenterX = Math.round(spineX(10));
  for (let x = vaultCenterX - 2; x <= vaultCenterX + 2; x++) {
    for (let y = 5; y <= 7; y++) {
      for (let z = 8; z <= 11; z++) {
        setBlock(x, y, z, null);
      }
    }
  }
  // Ensure solid floor under vault interior
  for (let x = vaultCenterX - 2; x <= vaultCenterX + 2; x++) {
    for (let z = 8; z <= 11; z++) {
      setBlock(x, 4, z, CALCITE);
    }
  }

  // 6. ENCRUSTATION & SCATTERED BONE SPLINTERS
  // Add ancient mineral crusting on ribs and salt flats
  for (let z = 14; z <= 48; z += 4) {
    const sx = spineX(z);
    const n1 = noise(sx + 8, SEAT_Y, z);
    if (n1 > 0.4) {
      setBlock(Math.round(sx + 10), SEAT_Y, z, DEAD_HORN);
      setBlock(Math.round(sx + 10), SEAT_Y + 1, z, stoneSlab);
    }
    const n2 = noise(sx - 8, SEAT_Y, z);
    if (n2 > 0.4) {
      setBlock(Math.round(sx - 10), SEAT_Y, z, DRIPSTONE);
      setBlock(Math.round(sx - 10), SEAT_Y + 1, z, stoneSlab);
    }
  }

  // 7. ONE CONNECTED SOLID CHECK (BFS Flood Fill)
  // Ensure all placed blocks form one 6-connected component
  const startX = Math.round(spineX(21));
  const startY = Math.round(spineY(21));
  const startZ = 21;

  const visited = new Uint8Array(W * H * D);
  const queue = [getIdx(startX, startY, startZ)];
  visited[queue[0]] = 1;

  let head = 0;
  while (head < queue.length) {
    const idx = queue[head++];
    const vx = idx % W;
    const vy = Math.floor(idx / (W * D));
    const vz = Math.floor(idx / W) % D;

    const neighbors = [
      [vx + 1, vy, vz],
      [vx - 1, vy, vz],
      [vx, vy + 1, vz],
      [vx, vy - 1, vz],
      [vx, vy, vz + 1],
      [vx, vy, vz - 1],
    ];

    for (let n = 0; n < 6; n++) {
      const [nx, ny, nz] = neighbors[n];
      const nIdx = getIdx(nx, ny, nz);
      if (nIdx !== -1 && !visited[nIdx] && grid[nIdx] !== null) {
        visited[nIdx] = 1;
        queue.push(nIdx);
      }
    }
  }

  // Remove disconnected floating fragments
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] !== null && !visited[i]) {
      grid[i] = null;
    }
  }

  // 8. TERRAIN CONFORMANCE (Rule 6)
  // Extend down to meet local ground heightAt(x, z) on slopes/shores/ridges
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let minY = -1;
      for (let y = 0; y < H; y++) {
        if (getBlock(x, y, z) !== null) {
          minY = y;
          break;
        }
      }

      if (minY !== -1) {
        const gh = api.heightAt(x, z);
        const realGroundY = Math.max(0, SEAT_Y + gh);

        // If ground drops below our structure, build downward skirt to anchor it
        if (realGroundY < minY) {
          for (let y = minY - 1; y >= realGroundY; y--) {
            const nVal = noise(x, y, z);
            const fillBlock = nVal < 0.4 ? CALCITE : groundPavement;
            setBlock(x, y, z, fillBlock);
          }
        }
        // If ground rises above seat plane, ensure solid footing up to hill level
        else if (realGroundY > SEAT_Y) {
          for (let y = SEAT_Y; y <= Math.min(H - 1, realGroundY); y++) {
            if (getBlock(x, y, z) === null) {
              setBlock(x, y, z, groundPavement);
            }
          }
        }
      }
    }
  }

  // 9. EMIT FINAL VOXELS IN DETERMINISTIC ORDER
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const blk = getBlock(x, y, z);
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  const skullX = Math.round(spineX(8));
  const frontX = Math.round(spineX(2));
  const tailX = Math.round(spineX(52));

  return {
    name: "ancient_leviathan_skeleton",
    seatY: SEAT_Y,
    anchors: {
      front: [frontX, SEAT_Y + 1, 0],
      skull: [skullX, 9, 8],
      tail: [tailX, SEAT_Y, 52],
    },
    interiors: [
      {
        min: [vaultCenterX - 2, 5, 8],
        max: [vaultCenterX + 2, 7, 11],
        kind: "vault",
      },
    ],
  };
}

